def exportToFile():
    headers = {
        "Authorization": "Bearer eyJ0eXAiOiJKV1QiLCJhbGciOiJSUzI1NiIsIng1dCI6InoxcnNZSEhKOS04bWdndDRIc1p1OEJLa0JQdyIsImtpZCI6InoxcnNZSEhKOS04bWdndDRIc1p1OEJLa0JQdyJ9..QuW-HarqgrMO4UX-q24WyQkZgS-CNalkHivoYmEzvOI8uUxAVluEvvNCqiNB4Z40oUtG8oUPFflkyFAfgrk6CAakJQlR1D5Q9sKypnDZ_mXEzbIE3OIJ5N7Msm_x7W7RNO87fxlicr43xfia3eIrr-SXOsXBMgwdkt43Hze_mZPBynUw0UeF3i7EFGldoOvbDixUmQqRFKMu-U5aXGGJoDQeZlIV0v_xTV2CgDkOTFd1cal-hL--M3cextiYxz1dN3o-lutcR2gyjYRM3W8jAbyeqM2Eq9oo0NFlQ1XWBJBLHTXlZklKQBFBA4KVuCZe9NHscaFzc8F7YsTgUBdoaA"}
    url = f"https://api.powerbi.com/v1.0/myorg/reports/{reportId}/exports/{exportId}/file"
    response = requests.get(url, headers=headers)
    # print(response.text)
    content_type = response.headers.get('Content-Type', '')
    print(content_type)
    if 'application/zip' in content_type:
        file_extension = '.zip'
    elif 'application/pdf' in content_type:
        file_extension = '.pdf'
    elif 'image/' in content_type:
        file_extension = '.png'  # 假设是 PNG 图片
    elif 'text/csv' in content_type:
        file_extension = '.csv'
    elif 'text/xml' in content_type:
        file_extension = '.xml'
    else:
        file_extension = '.dat'  #

    file_name = f"/Users/ning.zhou/Desktop/exported_file{file_extension}"

    # 将文件写入磁盘
    with open(file_name, 'wb') as file:
        file.write(response.content)


